ALTER TABLE users DROP CONSTRAINT IF EXISTS users_role_check;
ALTER TABLE users ADD CONSTRAINT users_role_check CHECK(role IN ('admin','protection_manager','supervisor','operator','viewer'));
ALTER TABLE measurement_points ADD COLUMN IF NOT EXISTS metric text NOT NULL DEFAULT 'voltage';
ALTER TABLE measurement_points ADD COLUMN IF NOT EXISTS enabled boolean NOT NULL DEFAULT true;
CREATE TABLE IF NOT EXISTS alarm_rules(id text PRIMARY KEY,point_id text NOT NULL REFERENCES measurement_points(id),name text NOT NULL,operator text NOT NULL DEFAULT 'gt',threshold double precision NOT NULL,severity text NOT NULL DEFAULT 'attention',enabled boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS telemetry_history(point_id text NOT NULL,ts timestamptz NOT NULL,value double precision NOT NULL,quality text NOT NULL,PRIMARY KEY(point_id,ts)) PARTITION BY RANGE(ts);
CREATE TABLE IF NOT EXISTS telemetry_history_default PARTITION OF telemetry_history DEFAULT;
CREATE TABLE IF NOT EXISTS telemetry_latest(point_id text PRIMARY KEY,asset_id text NOT NULL,metric text NOT NULL,value double precision NOT NULL,unit text NOT NULL,quality text NOT NULL,timestamp bigint NOT NULL);
CREATE TABLE IF NOT EXISTS topology_nodes(id text PRIMARY KEY,asset_id text REFERENCES assets(id) ON DELETE CASCADE,node_type text NOT NULL DEFAULT 'terminal',electrical_code text UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS topology_edges(id text PRIMARY KEY,from_node_id text REFERENCES topology_nodes(id),to_node_id text REFERENCES topology_nodes(id),line_id text REFERENCES power_lines(id) ON DELETE CASCADE,state text NOT NULL DEFAULT 'CLOSED',CHECK(state IN ('CLOSED','OPEN','UNKNOWN')));
CREATE TABLE IF NOT EXISTS topology_versions(id text PRIMARY KEY,version integer UNIQUE NOT NULL,published_at bigint NOT NULL,snapshot jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS protection_plans(id text PRIMARY KEY,event_id text REFERENCES protection_events(id),name text NOT NULL,content text NOT NULL,status text NOT NULL DEFAULT 'draft');
CREATE TABLE IF NOT EXISTS work_order_logs(id bigserial PRIMARY KEY,order_id text REFERENCES work_orders(id),actor_id text NOT NULL,action text NOT NULL,remark text NOT NULL,occurred_at bigint NOT NULL);
ALTER TABLE work_orders ADD COLUMN IF NOT EXISTS version integer NOT NULL DEFAULT 1;
ALTER TABLE alarms ADD COLUMN IF NOT EXISTS closed_at bigint;
ALTER TABLE alarms ADD COLUMN IF NOT EXISTS rule_id text REFERENCES alarm_rules(id);
ALTER TABLE alarms ADD COLUMN IF NOT EXISTS point_id text REFERENCES measurement_points(id);
CREATE UNIQUE INDEX IF NOT EXISTS alarms_one_active_rule ON alarms(rule_id) WHERE status='active' AND rule_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS scene_models(id text PRIMARY KEY,name text NOT NULL,file_key text UNIQUE NOT NULL,format text NOT NULL DEFAULT 'glb',size bigint NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'uploaded');
CREATE TABLE IF NOT EXISTS scene_bindings(scene_id text REFERENCES scenes(id),asset_id text REFERENCES assets(id) ON DELETE CASCADE,model_id text REFERENCES scene_models(id),transform jsonb NOT NULL DEFAULT '{}',PRIMARY KEY(scene_id,asset_id));
CREATE TABLE IF NOT EXISTS scene_layers(id text PRIMARY KEY,scene_id text REFERENCES scenes(id),name text NOT NULL,type text NOT NULL,visible boolean NOT NULL DEFAULT true,config jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS camera_presets(id text PRIMARY KEY,scene_id text REFERENCES scenes(id),name text NOT NULL,destination jsonb NOT NULL,orientation jsonb NOT NULL,duration double precision NOT NULL DEFAULT 2);
CREATE TABLE IF NOT EXISTS roles(id text PRIMARY KEY,name text NOT NULL,permissions jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS user_scopes(user_id text REFERENCES users(id) ON DELETE CASCADE,region_id text REFERENCES regions(id),PRIMARY KEY(user_id,region_id));
CREATE TABLE IF NOT EXISTS refresh_sessions(token_hash text PRIMARY KEY,user_id text REFERENCES users(id),expires_at bigint NOT NULL);
CREATE TABLE IF NOT EXISTS idempotency_keys(key text PRIMARY KEY,request_hash text NOT NULL,result jsonb NOT NULL,created_at bigint NOT NULL);
ALTER TABLE assets ADD COLUMN IF NOT EXISTS parent_id text REFERENCES assets(id);
ALTER TABLE regions ADD COLUMN IF NOT EXISTS parent_id text REFERENCES regions(id);
ALTER TABLE regions ADD COLUMN IF NOT EXISTS boundary jsonb;
